package com.campus.personnel.infrastructure.persistence;
import java.util.*; import com.campus.personnel.application.FacultyStaffManagementService.ConcurrentFacultyStaffModificationException; import com.campus.personnel.domain.*; import com.campus.personnel.infrastructure.persistence.entity.FacultyStaffEntity; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository class FacultyStaffPersistenceAdapter implements FacultyStaffRepository{ private final FacultyStaffJpaRepository repo; FacultyStaffPersistenceAdapter(FacultyStaffJpaRepository r){repo=r;} @Transactional public FacultyStaffMember save(FacultyStaffMember m){return managed(repo.findById(m.id()).orElseGet(()->new FacultyStaffEntity(m.id())),m);} @Transactional public FacultyStaffMember saveMutation(FacultyStaffMember m,long v){FacultyStaffEntity e=repo.findByIdForUpdate(m.id()).orElseThrow();if(e.getRowVersion()!=v)throw new ConcurrentFacultyStaffModificationException();return managed(e,m);} private FacultyStaffMember managed(FacultyStaffEntity e,FacultyStaffMember m){e.update(m.personnelNumber(),m.fullName(),m.email(),m.identityUserId(),m.personnelType(),m.organizationUnitId(),m.status());return map(repo.saveAndFlush(e));} @Transactional(readOnly=true) public Optional<FacultyStaffMember> findById(UUID id){return repo.findById(id).map(this::map);} @Transactional(readOnly=true) public boolean existsByPersonnelNumber(String n){return repo.existsByPersonnelNumber(n);} @Transactional(readOnly=true) public List<FacultyStaffMember> findAll(){return repo.findAll(org.springframework.data.domain.Sort.by("personnelNumber")).stream().map(this::map).toList();} @Transactional(readOnly=true) public com.campus.shared.application.PageResult<FacultyStaffMember> search(FacultyStaffSearch search){org.springframework.data.jpa.domain.Specification<FacultyStaffEntity> spec=(root,q,b)->{List<jakarta.persistence.criteria.Predicate> p=new ArrayList<>();if(search.query()!=null){String v="%"+search.query().toLowerCase(Locale.ROOT)+"%";p.add(b.or(b.like(b.lower(root.get("personnelNumber")),v),b.like(b.lower(root.get("fullName")),v),b.like(b.lower(root.get("email")),v)));}if(search.status()!=null)p.add(b.equal(root.get("status"),search.status()));if(search.personnelType()!=null)p.add(b.equal(root.get("personnelType"),search.personnelType()));return b.and(p.toArray(jakarta.persistence.criteria.Predicate[]::new));};org.springframework.data.domain.Sort sort=org.springframework.data.domain.Sort.by(search.ascending()?org.springframework.data.domain.Sort.Direction.ASC:org.springframework.data.domain.Sort.Direction.DESC,search.sortField()).and(org.springframework.data.domain.Sort.by("id"));var page=repo.findAll(spec,org.springframework.data.domain.PageRequest.of(search.page(),search.size(),sort));return new com.campus.shared.application.PageResult<>(page.getContent().stream().map(this::map).toList(),page.getTotalElements());} private FacultyStaffMember map(FacultyStaffEntity e){return new FacultyStaffMember(e.getId(),e.getPersonnelNumber(),e.getFullName(),e.getEmail(),e.getIdentityUserId(),e.getPersonnelType(),e.getOrganizationUnitId(),e.getStatus(),e.getRowVersion(),e.getCreatedAt(),e.getUpdatedAt());} }
